    // 规整播放地址：网页播放页 → /index.m3u8（金鹰/红牛模式）
    function normalizeStreamUrl(url) {
        if (!url) return url;
        if (/\.m3u8($|\?)/i.test(url)) return url;
        if (/^https?:/.test(url)) return url.replace(/\/+$/, '') + '/index.m3u8';
        return url;
    }

    // 解析速播的 vod_play_url（多线路）
    // 格式: "第1集$url1#第2集$url2$$$第1集$url1#第2集$url2"  ($$$ 分隔线路, # 分隔集, $ 分隔集名与链接)
    function parsePlayUrl(playUrlStr, playFromStr) {
        if (!playUrlStr) return { lines: [], episodes: [], m3u8Episodes: [], pageEpisodes: [] };
        const lineNames = (playFromStr || '').split(',').filter(Boolean);
        const lineStrs = String(playUrlStr).split('$$$').filter(Boolean);

        const rawLines = lineStrs.map((lineStr, i) => {
            const eps = lineStr.split('#').filter(Boolean).map(ep => {
                const [name, url] = ep.split('$');
                return { name: name || '未知集', url: normalizeStreamUrl(url || '') };
            });
            return { name: lineNames[i] || `线路${i + 1}`, episodes: eps };
        });

        // 去重：同一来源的多线路（网页播放页 + 其 /index.m3u8 直链）normalize 后 URL 相同，只保留一条
        const seen = new Set();
        const lines = rawLines.filter(l => {
            if (!l.episodes.length) return false;
            const key = l.episodes[0].url;
            if (!key || seen.has(key)) return false;
            seen.add(key);
            return true;
        });

        // 按集数对齐：m3u8 直链线路 与 网页播放页线路
        const m3u8Line = lines.find(l => l.episodes.some(e => /\.m3u8($|\?)/i.test(e.url))) || null;
        const pageLine = lines.find(l => l.episodes.some(e => !/\.m3u8($|\?)/i.test(e.url) && /^https?:/.test(e.url))) || null;

        const m3u8Episodes = (m3u8Line || { episodes: [] }).episodes;
        const pageEpisodes = (pageLine || { episodes: [] }).episodes;

        // 默认播放线路：优先 m3u8
        const episodes = m3u8Episodes.length ? m3u8Episodes : pageEpisodes;

        return { lines, episodes, m3u8Episodes, pageEpisodes };
    }

