    // 解析 m3u8，返回 { keyUrl, ivHex, segments[], totalDuration }
    async function parseM3u8(m3u8Text, m3u8Url) {
        const lines = m3u8Text.split('\n');
        let keyUrl = '', ivHex = '';
        const segments = [];
        let totalDuration = 0;
        const baseUrl = m3u8Url.slice(0, m3u8Url.lastIndexOf('/') + 1);

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();
            if (line.startsWith('#EXT-X-KEY')) {
                const m = line.match(/URI="([^"]+)"/);
                if (m) keyUrl = m[1].startsWith('http') ? m[1] : baseUrl + m[1];
                const ivm = line.match(/IV=0x([0-9a-fA-F]+)/);
                if (ivm) ivHex = ivm[1];
            } else if (line.startsWith('#EXTINF') && lines[i + 1] && !lines[i + 1].startsWith('#')) {
                const tm = line.match(/#EXTINF:\s*([\d.]+)/);
                if (tm) totalDuration += parseFloat(tm[1]);
                const seg = lines[i + 1].trim();
                segments.push(seg.startsWith('http') ? seg : baseUrl + seg);
            }
        }
        return { keyUrl, ivHex, segments, totalDuration };
    }

    // 下载单集（m3u8 → 解密 → mux.js 转 MP4）
    async function downloadSingleEpisode(ep, animeName, onProgress) {
        const { keyUrl, ivHex, segments, totalDuration } = await parseM3u8(
            await (await fetch(ep.url)).text(),
            ep.url
        );

        if (!segments.length) throw new Error('未找到视频分片');

        // 下载 key
        let keyBuf = new Uint8Array(16);
        if (keyUrl) {
            keyBuf = new Uint8Array(await (await fetch(keyUrl)).arrayBuffer());
        }
        const iv = ivHex ? hexToBytes(ivHex) : new Uint8Array(16);

        // 导入 AES key
        const cryptoKey = await crypto.subtle.importKey(
            'raw', keyBuf, { name: 'AES-CBC' }, false, ['decrypt']
        );

        // 逐分片下载 + 解密
        const tsParts = [];
        for (let i = 0; i < segments.length; i++) {
            const enc = new Uint8Array(await (await fetch(segments[i])).arrayBuffer());
            const dec = await crypto.subtle.decrypt({ name: 'AES-CBC', iv }, cryptoKey, enc);
            tsParts.push(new Uint8Array(dec));
            if (onProgress) onProgress((i + 1) / segments.length, `下载解密 ${i + 1}/${segments.length}`);
        }

        // 拼接 TS
        const totalLen = tsParts.reduce((s, p) => s + p.length, 0);
        const ts = new Uint8Array(totalLen);
        let off = 0;
        for (const p of tsParts) { ts.set(p, off); off += p.length; }

        // mux.js 转 MP4（失败则直接下载 .ts）
        try {
            if (window.muxjs && muxjs.mp4) {
                const mp4 = await tsToMp4(ts, totalDuration);
                if (onProgress) onProgress(1, '转换完成');
                return { blob: mp4, ext: 'mp4', name: sanitizeFileName((animeName || '') + '_' + (ep.name || '第' + '集')) };
            }
        } catch (e) { console.warn('MP4 转换失败，回退 TS:', e); }

        return { blob: new Blob([ts], { type: 'video/mp2t' }), ext: 'ts', name: sanitizeFileName((animeName || '') + '_' + (ep.name || '第' + '集')) };
    }

