    // 生成星星和流星
    function generateStars() {
        const starfield = document.getElementById('starfield');

        // 生成闪烁星星
        for (let i = 0; i < 60; i++) {
            const star = document.createElement('div');
            star.className = 'twinkle-star';
            star.style.left = Math.random() * 100 + '%';
            star.style.top = Math.random() * 100 + '%';
            star.style.animationDelay = Math.random() * 3 + 's';
            const hue = Math.random() * 360;
            star.style.setProperty('--hue', hue);
            star.style.boxShadow = `0 0 8px hsl(${hue}, 80%, 60%)`;
            starfield.appendChild(star);
        }

        // 生成流星
        for (let i = 0; i < 13; i++) {
            const meteor = document.createElement('div');
            meteor.className = 'shooting-star';
            meteor.style.left = Math.random() * 100 + '%';
            meteor.style.animationDelay = Math.random() * 8 + 's';
            meteor.style.top = Math.random() * 100 + '%';
            starfield.appendChild(meteor);
        }
    }

    // 更新时间和倒计时
    function updateTime() {
        const target = new Date('2025-04-28T13:30:00+08:00');
        const now = new Date();

        // 当前时间
        document.getElementById('current-time').textContent =
            `当前时间：${now.toLocaleString('zh-CN', {
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false
            })}`;

        // 倒计时秒数
        const diffSeconds = Math.floor((target - now) / 1000);
        document.getElementById('countdown').textContent =
            `${Math.abs(diffSeconds)} 秒 (约 ${Math.abs(Math.round(diffSeconds/3600))} 小时)`;

        // 剩余天数
        const diffDays = Math.floor(diffSeconds / (3600 * 24));
        document.getElementById('days-left').textContent =
            `已过天数：${Math.abs(diffDays)} 天`;
    }

    // 初始化
    document.addEventListener('DOMContentLoaded', function() {
        generateStars();
        updateTime();
        setInterval(updateTime, 1000);

        // 音频处理函数
        function handleAudioPlay() {
            const audio = document.querySelector('audio');
            if(audio) {
                audio.volume = 0.5;
                audio.play().catch(e => {
                    console.log("播放失败:", e);
                    // 显示提示让用户点击
                    showPlayHint();
                });
            }
        }

        // 显示播放提示
        function showPlayHint() {
            const hint = document.createElement('div');
            hint.innerHTML = '点击任意处播放音乐';
            hint.style.position = 'fixed';
            hint.style.bottom = '70px';
            hint.style.left = '50%';
            hint.style.transform = 'translateX(-50%)';
            hint.style.backgroundColor = 'rgba(0,0,0,0.7)';
            hint.style.padding = '10px 20px';
            hint.style.borderRadius = '20px';
            hint.style.zIndex = '100';
            hint.style.cursor = 'pointer';
            hint.onclick = function() {
                document.body.removeChild(hint);
                handleAudioPlay();
            };
            document.body.appendChild(hint);
        }

        // 首次尝试播放
        handleAudioPlay();

        // 点击任意位置尝试播放
        document.addEventListener('click', function() {
            handleAudioPlay();
        }, { once: true });
    });



