  // 高考日期（2026年6月7日9:00）
  const examDate = new Date(2026, 5, 7, 9, 0, 0);

  // 更新倒计时
  function updateCountdown() {
    const now = new Date();
    const diff = examDate - now;

    if (diff  50) {
      const loader = document.getElementById('initial-loader');
      loader.style.opacity = '0';
      loader.style.pointerEvents = 'none';

      // 显示主内容
      document.querySelector('.main-content').style.opacity = '1';
      document.querySelector('.main-content').style.transform = 'translateY(0)';

      // 添加卡片动画
      setTimeout(() => {
        document.querySelectorAll('.card').forEach((card, index) => {
          setTimeout(() => {
            card.classList.add('card-visible');
          }, index * 200);
        });
      }, 300);

      // 移除滚动监听器
      window.removeEventListener('scroll', handleScroll);
    }
  }

  // 创建粒子渐入效果
  function createParticleEffect() {
    const particlesContainer = document.getElementById('particles-js');

    // 添加粒子渐入动画
    particlesContainer.style.animation = 'particleFadeIn 0.8s ease-out forwards';

    // 动画结束后移除样式
    setTimeout(() => {
      particlesContainer.style.animation = '';
    }, 800);
  }

  // 初始化
  document.addEventListener('DOMContentLoaded', () => {
    // 倒计时初始化
    updateCountdown();
    setInterval(updateCountdown, 1000);

    // 添加滚动监听器
    window.addEventListener('scroll', handleScroll);

    // 点击下滑提示滚动页面
    document.getElementById('scroll-hint').addEventListener('click', () => {
      window.scrollTo({
        top: window.innerHeight,
        behavior: 'smooth'
      });
    });

    // 按钮事件
    const sloganElement = document.getElementById('slogan');
    const generateBtn = document.getElementById('generateBtn');

    // 防重复点击机制
    let clickAllowed = true;

    generateBtn.addEventListener('click', () => {
      if (!clickAllowed) return;
      clickAllowed = false;

      sloganElement.style.animation = 'none';

      // 随机选择一条祝福语
      const randomIndex = Math.floor(Math.random() * messages.length);
      const randomMessage = messages[randomIndex];

      // 重置动画并更新内容
      setTimeout(() => {
        sloganElement.style.animation = 'fadeIn 1s ease';
        sloganElement.textContent = randomMessage;
      }, 10);

      // 创建粒子渐入效果
      createParticleEffect();

      // 1.5秒后解锁按钮
      setTimeout(() => {
        clickAllowed = true;
      }, 1500);
    });

    // 5秒后如果用户没有滚动，自动显示主内容
    setTimeout(() => {
      if (window.scrollY === 0) {
        handleScroll();
      }
    }, 5000);
  });

