    .start-title {
        text-align: center;
        font-size: 3.5rem;
        color: #e1e6ff;
        text-shadow: 0 0 20px rgba(101, 80, 255, 0.8);
        margin-bottom: 20px;
        letter-spacing: 3px;
        font-weight: 800;
        position: relative;
    }

    .start-title::after {
        content: '';
        position: absolute;
        bottom: -10px;
        left: 50%;
        transform: translateX(-50%);
        width: 150px;
        height: 3px;
        background: linear-gradient(90deg, transparent, #6550ff, transparent);
    }

    .start-subtitle {
        text-align: center;
        color: #a0a8ff;
        font-size: 1.2rem;
        margin-bottom: 40px;
        max-width: 600px;
        line-height: 1.6;
    }

    .start-options {
        margin-bottom: 40px;
    }

    .option-group {
        margin-bottom: 25px;
    }

    .option-title {
        font-size: 1.4rem;
        color: #e1e6ff;
        margin-bottom: 15px;
        display: flex;
        align-items: center;
    }

    .option-title::before {
        content: '▶';
        color: #ffcc00;
        margin-right: 10px;
        font-size: 0.8rem;
    }

    .difficulty-options {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
        gap: 12px;
    }

    .start-difficulty-option {
        background: rgba(16, 24, 48, 0.7);
        border: 1px solid rgba(101, 80, 255, 0.3);
        color: #e1e6ff;
        padding: 12px 5px;
        border-radius: 8px;
        cursor: pointer;
        text-align: center;
        transition: all 0.3s ease;
        position: relative;
        overflow: hidden;
    }

    .start-difficulty-option:hover {
        background: rgba(101, 80, 255, 0.4);
        transform: translateY(-3px);
        box-shadow: 0 5px 15px rgba(101, 80, 255, 0.3);
    }

    .start-difficulty-option.active {
        background: rgba(101, 80, 255, 0.6);
        border-color: #6550ff;
        box-shadow: 0 0 15px rgba(101, 80, 255, 0.5);
    }

    .ai-toggle-container {
        display: flex;
        align-items: center;
        background: rgba(16, 24, 48, 0.7);
        border: 1px solid rgba(255, 165, 0, 0.3);
        border-radius: 8px;
        padding: 15px;
        transition: all 0.3s ease;
    }

    .ai-toggle-container:hover {
        background: rgba(255, 165, 0, 0.2);
        transform: translateY(-3px);
        box-shadow: 0 5px 15px rgba(255, 165, 0, 0.2);
    }

    .ai-toggle-label {
        flex-grow: 1;
        font-size: 1.1rem;
        color: #e1e6ff;
    }

    .ai-toggle {
        position: relative;
        width: 60px;
        height: 30px;
    }

    .ai-toggle input {
        opacity: 0;
        width: 0;
        height: 0;
    }

    .ai-toggle-slider {
        position: absolute;
        cursor: pointer;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: rgba(255, 68, 68, 0.5);
        transition: .4s;
        border-radius: 30px;
    }

    .ai-toggle-slider:before {
        position: absolute;
        content: "";
        height: 22px;
        width: 22px;
        left: 4px;
        bottom: 4px;
        background-color: #e1e6ff;
        transition: .4s;
        border-radius: 50%;
    }

    input:checked + .ai-toggle-slider {
        background-color: rgba(0, 200, 83, 0.7);
    }

    input:checked + .ai-toggle-slider:before {
        transform: translateX(30px);
    }

    .start-button {
        display: block;
        width: 100%;
        max-width: 300px;
        margin: 0 auto;
        background: linear-gradient(135deg, #6550ff, #8a7cff);
        border: none;
        color: #e1e6ff;
        padding: 15px;
        font-size: 1.4rem;
        border-radius: 8px;
        cursor: pointer;
        transition: all 0.3s ease;
        font-weight: bold;
        letter-spacing: 1px;
        text-transform: uppercase;
        position: relative;
        overflow: hidden;
        z-index: 1;
    }

    .start-button::before {
        content: '';
        position: absolute;
        top: -2px;
        left: -2px;
        right: -2px;
        bottom: -2px;
        background: linear-gradient(135deg,
            #6550ff, #8a7cff,
            #ffcc00, #ff3366,
            #6550ff, #8a7cff);
        background-size: 300% 300%;
        z-index: -1;
        border-radius: 10px;
        animation: gradientBG 3s ease infinite;
    }

    .start-button:hover {
        transform: scale(1.05);
        box-shadow: 0 0 30px rgba(101, 80, 255, 0.6);
    }

    .start-button:active {
        transform: scale(0.98);
    }

    @keyframes scanLine {
        0% { transform: translateY(-100%); }
        100% { transform: translateY(100%); }
    }

    @keyframes gradientBG {
        0% { background-position: 0% 50%; }
        50% { background-position: 100% 50%; }
        100% { background-position: 0% 50%; }
    }

    .game-container {
        position: relative;
        width: 100%;
        max-width: 900px;
        background: rgba(12, 16, 39, 0.8);
        border-radius: 16px;
        box-shadow: 0 0 40px rgba(101, 80, 255, 0.3);
        overflow: hidden;
        border: 1px solid rgba(101, 80, 255, 0.3);
        backdrop-filter: blur(10px);
    }

    .game-header {
        text-align: center;
        padding: 5px;
        background: rgba(0, 0, 0, 0.4);
        border-bottom: 1px solid rgba(101, 80, 255, 0.3);
    }

    .game-title {
        color: #e1e6ff;
        font-size: 2.5rem;
        margin-bottom: 10px;
        text-shadow: 0 0 15px #6550ff;
        letter-spacing: 2px;
        font-weight: 700;
    }

    .game-subtitle {
        color: #a0a8ff;
        font-size: 1.1rem;
        opacity: 0.8;
    }

    .game-stats {
        display: flex;
        justify-content: space-between;
        padding: 5px 30px;
        background: rgba(16, 20, 45, 0.7);
        position: relative;
    }

    .player-stats {
        display: flex;
        flex-direction: column;
        align-items: center;
        position: relative;
    }

    .player-name {
        font-size: 1.2rem;
        margin-bottom: 5px;
        color: #a0a8ff;
    }

    .player-score {
        font-size: 2.5rem;
        font-weight: bold;
        color: #ffcc00;
        text-shadow: 0 0 10px rgba(255, 204, 0, 0.5);
        position: relative;
    }

    .score-animation {
        position: absolute;
        font-size: 3rem;
        color: #ff3366;
        opacity: 0;
        animation: scorePopup 1s forwards;
        pointer-events: none;
        z-index: 10;
        text-shadow: 0 0 15px rgba(255, 51, 102, 0.7);
    }

    @keyframes scorePopup {
        0% {
            transform: translateY(0);
            opacity: 1;
        }
        100% {
            transform: translateY(-100px);
            opacity: 0;
        }
    }

    .game-content {
        position: relative;
        display: flex;
        justify-content: center;
        padding: 20px;
    }

    #game-canvas {
        background: rgba(8, 12, 33, 0.7);
        border-radius: 8px;
        box-shadow: 0 0 30px rgba(101, 80, 255, 0.2);
        border: 1px solid rgba(101, 80, 255, 0.2);
    }

    .controls-info {
        text-align: center;
        padding: 15px;
        font-size: 1rem;
        color: #a0a8ff;
        background: rgba(16, 20, 45, 0.6);
        border-top: 1px solid rgba(101, 80, 255, 0.2);
    }

    .particle {
        position: absolute;
        pointer-events: none;
        border-radius: 50%;
        background: #ffcc00;
        opacity: 0.8;
    }

    .center-line {
        position: absolute;
        top: 0;
        bottom: 0;
        left: 50%;
        width: 2px;
        background: linear-gradient(to bottom,
            transparent 0%,
            rgba(101, 80, 255, 0.5) 10%,
            rgba(101, 80, 255, 0.8) 50%,
            rgba(101, 80, 255, 0.5) 90%,
            transparent 100%);
        transform: translateX(-50%);
    }

    .glow-effect {
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        border-radius: 16px;
        box-shadow: inset 0 0 30px rgba(101, 80, 255, 0.5);
        pointer-events: none;
        z-index: -1;
    }

    .victory-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(12, 16, 39, 0.85);
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        z-index: 100;
        opacity: 0;
        pointer-events: none;
        transition: opacity 0.5s ease;
    }

    .victory-message {
        font-size: 4rem;
        font-weight: bold;
        color: #ffcc00;
        text-shadow: 0 0 20px rgba(255, 204, 0, 0.8);
        margin-bottom: 30px;
        text-align: center;
        animation: pulse 1.5s infinite;
    }

    .restart-btn {
        background: rgba(101, 80, 255, 0.5);
        border: 2px solid #a0a8ff;
        color: #e1e6ff;
        padding: 12px 35px;
        font-size: 1.2rem;
        border-radius: 8px;
        cursor: pointer;
        transition: all 0.3s ease;
        font-weight: bold;
        letter-spacing: 1px;
    }

    .restart-btn:hover {
        background: rgba(101, 80, 255, 0.8);
        transform: scale(1.05);
        box-shadow: 0 0 20px rgba(101, 80, 255, 0.5);
    }

    @keyframes pulse {
        0% { transform: scale(1); text-shadow: 0 0 20px rgba(255, 204, 0, 0.8); }
        50% { transform: scale(1.1); text-shadow: 0 0 30px rgba(255, 204, 0, 1); }
        100% { transform: scale(1); text-shadow: 0 0 20px rgba(255, 204, 0, 0.8); }
    }

    .obstacle-warning {
        position: absolute;
        border-radius: 50%;
        pointer-events: none;
        z-index: 5;
        animation: warningPulse 0.5s infinite alternate;
    }

    @keyframes warningPulse {
        0% { opacity: 0.3; transform: scale(0.8); }
        100% { opacity: 0.7; transform: scale(1.1); }
    }

    /* 事件弹窗样式 */
    .event-notification {
        position: fixed;
        top: 20px;
        right: 20px;
        background: rgba(12, 16, 39, 0.95);
        border: 2px solid;
        border-radius: 12px;
        padding: 15px 20px;
        min-width: 250px;
        max-width: 350px;
        z-index: 1000;
        transform: translateX(100%);
        transition: transform 0.5s ease, opacity 0.5s ease;
        backdrop-filter: blur(10px);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    }

    .event-notification.show {
        transform: translateX(0);
        opacity: 1;
    }

    .event-notification.positive {
        border-color: #00ff88;
        box-shadow: 0 0 20px rgba(0, 255, 136, 0.3);
    }

    .event-notification.neutral {
        border-color: #888888;
        box-shadow: 0 0 20px rgba(136, 136, 136, 0.3);
    }

    .event-notification.negative {
        border-color: #ff4444;
        box-shadow: 0 0 20px rgba(255, 68, 68, 0.3);
    }

    .event-title {
        font-size: 1.2rem;
        font-weight: bold;
        margin-bottom: 5px;
        color: #e1e6ff;
    }

    .event-description {
        font-size: 0.9rem;
        color: #a0a8ff;
        line-height: 1.4;
    }

    .event-trigger {
        font-size: 0.8rem;
        color: #ffcc00;
        margin-bottom: 8px;
        font-weight: bold;
    }

    @keyframes slideInRight {
        from {
            transform: translateX(100%);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }

    @keyframes slideOutRight {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(100%);
            opacity: 0;
        }
    }

    /* 暂停/重新开始按钮样式 */
    .pause-button {
        position: fixed;
        top: 20px;
        right: 5%;
        transform: translateX(50%);
        background: rgba(101, 80, 255, 0.8);
        border: 2px solid rgba(101, 80, 255, 0.9);
        color: #e1e6ff;
        padding: 12px 24px;
        font-size: 1rem;
        border-radius: 8px;
        cursor: pointer;
        transition: all 0.3s ease;
        font-weight: bold;
        letter-spacing: 1px;
        z-index: 1000;
        backdrop-filter: blur(10px);
        box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
    }

    .pause-button:hover {
        background: rgba(101, 80, 255, 1);
        transform: translateX(50%) scale(1.05);
        box-shadow: 0 0 20px rgba(101, 80, 255, 0.6);
    }

    .pause-button.paused {
        background: rgba(255, 68, 68, 0.8);
        border-color: rgba(255, 68, 68, 0.9);
    }

    .pause-button.paused:hover {
        background: rgba(255, 68, 68, 1);
        box-shadow: 0 0 20px rgba(255, 68, 68, 0.6);
    }

    /* 调试窗口样式 */
    .debug-panel {
        position: fixed;
        top: 20px;
        left: 20px;
        background: rgba(12, 16, 39, 0.95);
        border: 2px solid rgba(255, 68, 68, 0.5);
        border-radius: 12px;
        padding: 15px;
        width: 60px;
        height: 60px;
        z-index: 1000;
        transition: all 0.3s ease;
        backdrop-filter: blur(10px);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
        cursor: pointer;
        overflow: hidden;
    }

    .debug-panel:hover {
        width: 280px;
        height: 420px;
        cursor: default;
    }

    .debug-icon {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        font-size: 24px;
        color: #ff4444;
        transition: opacity 0.3s ease;
    }

    .debug-panel:hover .debug-icon {
        opacity: 0;
    }

    .debug-content {
        opacity: 0;
        transition: opacity 0.3s ease 0.1s;
        height: 100%;
        display: flex;
        flex-direction: column;
        font-size: 0.85rem;
    }

    .debug-panel:hover .debug-content {
        opacity: 1;
    }

    .debug-title {
        color: #e1e6ff;
        font-size: 1.1rem;
        font-weight: bold;
        margin-bottom: 15px;
        text-align: center;
        border-bottom: 1px solid rgba(255, 68, 68, 0.3);
        padding-bottom: 8px;
    }

    .debug-section {
        margin-bottom: 12px;
    }

    .debug-section-title {
        color: #ff4444;
        font-weight: bold;
        margin-bottom: 5px;
        font-size: 0.9rem;
    }

    .debug-item {
        color: #a0a8ff;
        margin: 2px 0;
        display: flex;
        justify-content: space-between;
    }

    .debug-label {
        color: #e1e6ff;
    }

    .debug-value {
        color: #ffcc00;
        font-weight: bold;
    }

    /* 难度调整窗口样式 */
    .difficulty-panel {
        position: fixed;
        top: 50%;
        right: 20px;
        transform: translateY(-50%);
        background: rgba(12, 16, 39, 0.95);
        border: 2px solid rgba(101, 80, 255, 0.5);
        border-radius: 12px;
        padding: 15px;
        width: 60px;
        height: 60px;
        z-index: 1000;
        transition: all 0.3s ease;
        backdrop-filter: blur(10px);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
        cursor: pointer;
        overflow: hidden;
    }

    .difficulty-panel:hover {
        width: 200px;
        height: 320px;
        cursor: default;
    }

    .difficulty-icon {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        font-size: 24px;
        color: #6550ff;
        transition: opacity 0.3s ease;
    }

    .difficulty-panel:hover .difficulty-icon {
        opacity: 0;
    }

    .difficulty-content {
        opacity: 0;
        transition: opacity 0.3s ease 0.1s;
        height: 100%;
        display: flex;
        flex-direction: column;
    }

    .difficulty-panel:hover .difficulty-content {
        opacity: 1;
    }

    .difficulty-title {
        color: #e1e6ff;
        font-size: 1.1rem;
        font-weight: bold;
        margin-bottom: 15px;
        text-align: center;
    }

    .difficulty-option {
        background: rgba(101, 80, 255, 0.3);
        border: 1px solid rgba(101, 80, 255, 0.5);
        color: #e1e6ff;
        padding: 8px 12px;
        margin: 3px 0;
        border-radius: 6px;
        cursor: pointer;
        transition: all 0.2s ease;
        font-size: 0.9rem;
        text-align: center;
    }

    .difficulty-option:hover {
        background: rgba(101, 80, 255, 0.6);
        transform: scale(1.02);
    }

    .difficulty-option.active {
        background: rgba(101, 80, 255, 0.8);
        border-color: #6550ff;
        box-shadow: 0 0 10px rgba(101, 80, 255, 0.5);
    }

    /* 电脑回球增强选项样式 */
    .ai-enhancement-option {
        background: rgba(255, 165, 0, 0.3);
        border: 1px solid rgba(255, 165, 0, 0.5);
        color: #e1e6ff;
        padding: 8px 12px;
        margin: 8px 0;
        border-radius: 6px;
        cursor: pointer;
        transition: all 0.2s ease;
        font-size: 0.9rem;
        text-align: center;
    }

    .ai-enhancement-option:hover {
        background: rgba(255, 165, 0, 0.6);
        transform: scale(1.02);
    }

    .ai-enhancement-option.active {
        background: rgba(255, 165, 0, 0.8);
        border-color: #ffa500;
        box-shadow: 0 0 10px rgba(255, 165, 0, 0.5);
    }

    @media (max-width: 768px) {
        .game-title {
            font-size: 2rem;
        }

        .game-subtitle {
            font-size: 0.9rem;
        }

        .player-name {
            font-size: 1rem;
        }

        .player-score {
            font-size: 2rem;
        }

        .victory-message {
            font-size: 2.5rem;
        }

        .event-notification {
            top: 10px;
            right: 10px;
            min-width: 200px;
            max-width: 280px;
            padding: 12px 15px;
        }

        .event-title {
            font-size: 1rem;
        }

        .event-description {
            font-size: 0.8rem;
        }

        .difficulty-panel {
            right: 10px;
            width: 50px;
            height: 50px;
        }

        .difficulty-panel:hover {
            width: 180px;
            height: 280px;
        }

        .difficulty-icon {
            font-size: 20px;
        }

        .debug-panel {
            left: 10px;
            width: 50px;
            height: 50px;
        }

        .debug-panel:hover {
            width: 260px;
            height: 300px;
        }

        .debug-icon {
            font-size: 20px;
        }

        .pause-button {
            top: 10px;
            padding: 10px 20px;
            font-size: 0.9rem;
        }

        /* 移动端虚拟按钮样式 */
        .mobile-controls {
            position: fixed;
            bottom: 20px;
            left: 20px;
            z-index: 3000;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .mobile-btn {
            width: 60px;
            height: 60px;
            border-radius: 50%;
            border: none;
            background: rgba(101, 80, 255, 0.8);
            color: white;
            font-size: 24px;
            font-weight: bold;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
            transition: all 0.2s ease;
            user-select: none;
            -webkit-user-select: none;
            -webkit-touch-callout: none;
        }

        .mobile-btn:active {
            transform: scale(0.95);
            background: rgba(101, 80, 255, 1);
        }

        .mobile-btn.up {
            background: rgba(0, 200, 83, 0.8);
        }

        .mobile-btn.down {
            background: rgba(255, 68, 68, 0.8);
        }

        /* 移动端开始页面优化 */
        .start-container {
            margin: 10px;
            padding: 20px;
        }

        .start-title {
            font-size: 2.5rem;
        }

        .start-subtitle {
            font-size: 1rem;
        }

        .difficulty-options {
            grid-template-columns: repeat(2, 1fr);
            gap: 8px;
        }

        .start-difficulty-option {
            padding: 8px 4px;
            font-size: 0.9rem;
        }

        .ai-toggle-label {
            font-size: 1rem;
        }

        .start-button {
            padding: 12px;
            font-size: 1.2rem;
        }

        /* 移动端游戏容器优化 */
        .game-container {
            margin: 5px;
            border-radius: 12px;
        }

        .game-content {
            padding: 10px;
        }

        .controls-info {
            font-size: 0.8rem;
            padding: 10px;
        }
    }

    /* 超小屏幕优化 */
    @media (max-width: 480px) {
        .game-title {
            font-size: 1.5rem;
        }

        .game-subtitle {
            font-size: 0.8rem;
        }

        .player-score {
            font-size: 1.5rem;
        }

        .victory-message {
            font-size: 2rem;
        }

        .mobile-btn {
            width: 50px;
            height: 50px;
            font-size: 20px;
        }

        .start-title {
            font-size: 2rem;
        }

        .difficulty-options {
            grid-template-columns: 1fr;
        }

        .start-difficulty-option {
            font-size: 0.8rem;
        }
    }

    /* 移动端触摸优化 */
    @media (max-width: 768px) {
        body {
            overflow: hidden;
            position: fixed;
            width: 100%;
            height: 100%;
            touch-action: none;
            -webkit-overflow-scrolling: touch;
        }

        canvas {
            touch-action: none;
            -webkit-user-select: none;
            -moz-user-select: none;
            -ms-user-select: none;
            user-select: none;
        }

        /* 防止双击缩放 */
        * {
            -webkit-touch-callout: none;
            -webkit-user-select: none;
            -khtml-user-select: none;
            -moz-user-select: none;
            -ms-user-select: none;
            user-select: none;
        }

        /* 虚拟按钮触摸反馈 */
        .mobile-btn {
            -webkit-tap-highlight-color: transparent;
        }

        .mobile-btn:active {
