            ctx.beginPath();
            ctx.arc(ball.trail[i].x, ball.trail[i].y, radius, 0, Math.PI * 2);
            ctx.fillStyle = ball.color;
            ctx.fill();
            ctx.closePath();
            ctx.restore();
        }
